import sys
input = sys.stdin.read
data = input().split()

r, s, p = map(int, data)

# Initialize a 3D DP array
dp = [[[0.0 for _ in range(p+1)] for _ in range(s+1)] for _ in range(r+1)]

# Base cases
for i in range(1, r+1):
    dp[i][0][0] = 1.0
for j in range(1, s+1):
    dp[0][j][0] = 1.0
for k in range(1, p+1):
    dp[0][0][k] = 1.0

# Fill the DP table
for i in range(r+1):
    for j in range(s+1):
        for k in range(p+1):
            total_pairs = i*j + j*k + k*i
            if total_pairs == 0:
                continue
            if i > 0 and j > 0:
                dp[i][j][k] += dp[i][j-1][k] * (i * j) / total_pairs
            if j > 0 and k > 0:
                dp[i][j][k] += dp[i][j][k-1] * (j * k) / total_pairs
            if k > 0 and i > 0:
                dp[i][j][k] += dp[i-1][j][k] * (k * i) / total_pairs

# The probabilities we need
prob_rock = dp[r][s][p]
prob_scissors = dp[r][s][p]
prob_paper = dp[r][s][p]

for i in range(1, r+1):
    prob_rock += dp[i][0][0]

for j in range(1, s+1):
    prob_scissors += dp[0][j][0]

for k in range(1, p+1):
    prob_paper += dp[0][0][k]

print(f"{prob_rock:.12f}")
print(f"{prob_scissors:.12f}")
print(f"{prob_paper:.12f}")

