import sys
input = sys.stdin.read
data = input().split()

r, s, p = map(int, data)

def solve(r, s, p):
    dp = [[[0.0] * 101 for _ in range(101)] for _ in range(101)]
    dp[r][s][p] = 1.0

    for i in range(r, -1, -1):
        for j in range(s, -1, -1):
            for k in range(p, -1, -1):
                total = i * j + j * k + k * i
                if total == 0:
                    continue
                if i > 0:
                    dp[i - 1][j][k] += dp[i][j][k] * (i * k) / total
                if j > 0:
                    dp[i][j - 1][k] += dp[i][j][k] * (j * i) / total
                if k > 0:
                    dp[i][j][k - 1] += dp[i][j][k] * (k * j) / total

    res_r = res_s = res_p = 0.0
    for i in range(101):
        for j in range(101):
            res_r += dp[i][0][0]
            res_s += dp[0][j][0]
            res_p += dp[0][0][j]

    return res_r, res_s, res_p

results = solve(r, s, p)
for result in results:
    print("{:.12f}".format(result))

